package org.poetrymemory.poetry

import android.os.Bundle
import android.widget.EditText
import com.google.gson.*
import org.poetrymemory.core.*

class PoemEditorActivity: PoetryActivity() {
    private lateinit var entry:PoemStore.Entry
    private lateinit var draft:JsonObject
    private var base=""
    private val key get()=intent.getStringExtra("key")!!
    private var flush:()->Unit={}
    private var discarded=false
    override fun onCreate(state:Bundle?){super.onCreate(state);entry=poems.entry(key)?:run{finish();return};val old=poems.state("draft:$key");draft=old.getAsJsonObject("poem")?.deepCopy()?:entry.poem.deepCopy();base=old.s("base").ifBlank{Poetry.revision(entry.poem)};metadata()}
    private fun persist(){if(!discarded){flush();poems.save("draft:$key",JsonObject().apply{add("poem",draft);addProperty("base",base)})}}
    private fun header(title:String){persist();page(title,{metadata()});headerActions.addView(ui.primaryButton("保存正文"){save()});menu(listOf("退出并保留草稿" to {persist();finish()},"取消并放弃" to {discarded=true;poems.save("draft:$key",JsonObject());finish()}))}
    private fun fields(names:List<Pair<String,String>>,owner:JsonObject){val inputs=names.associate{(k,label)->k to ui.field(label,owner.s(k),k !in listOf("title","author","dynasty","genre")).also{panel.addView(it)}};flush={inputs.forEach{(k,input)->owner.addProperty(k,input.text.toString())}};inputs.values.forEach{ui.watch(it){persist()}}}
    private fun metadata(){header("编辑诗文 · 草稿");panel.addView(ui.text("草稿与正式正文分开保存；保存时比较内容版本。",14f));fields(listOf("title" to "标题","author" to "作者","dynasty" to "朝代","genre" to "体裁"),draft);val previous=flush;val tags=ui.field("内容标签，逗号分隔",draft.getAsJsonArray("tags")?.joinToString(","){it.asString}.orEmpty());panel.addView(tags);flush={previous();draft.add("tags",JsonArray().apply{tags.text.toString().split('，',',').map{it.trim()}.filter{it.isNotBlank()}.forEach{add(it)}})};ui.watch(tags){persist()};panel.addView(ui.button("逐句编辑、重排和分节"){lineList()});panel.addView(ui.button("篇级资料"){header("篇级资料");fields(listOf("background" to "创作背景","translation" to "全篇译文","appreciation" to "赏析"),draft)})}
    private fun lineList(){header("逐句编辑");flush={};var n=0;draft.getAsJsonArray("stanzas").forEachIndexed{si,s->panel.addView(ui.text("第 ${si+1} 节",14f));s.asJsonObject.getAsJsonArray("lines").forEach{l->val index=n++;panel.addView(ui.button("${index+1}. ${l.asJsonObject.s("original")}"){line(index)})}};panel.addView(ui.button("末尾添加句子"){draft.getAsJsonArray("stanzas").last().asJsonObject.getAsJsonArray("lines").add(JsonObject().apply{addProperty("id",Poetry.id());addProperty("original","新句子")});persist();lineList()})}
    private fun flatten():MutableList<JsonObject> = Poetry.lines(draft).map{it.deepCopy().apply{}}.toMutableList()
    private fun applyLines(lines:List<JsonObject>){val stanzas=draft.getAsJsonArray("stanzas");val originalStanza=mutableMapOf<String,String>();stanzas.forEach{s->s.asJsonObject.getAsJsonArray("lines").forEach{originalStanza[it.asJsonObject.s("id")]=s.asJsonObject.s("id")}};val result=JsonArray();var current:JsonObject?=null;var last="";lines.forEach{l->val sid=l.s("_section").ifBlank{originalStanza[l.s("id")]?:last.ifBlank{Poetry.id()}};l.remove("_section");if(current==null||last!=sid){current=JsonObject().apply{addProperty("id",if(result.any{it.asJsonObject.s("id")==sid})Poetry.id()else sid);add("lines",JsonArray())};result.add(current)};current!!.getAsJsonArray("lines").add(l);last=sid};draft.add("stanzas",result);persist()}
    private fun line(i:Int){header("第 ${i+1} 句");val rows=flatten();val l=rows[i];fields(listOf("original" to "原文","pinyin" to "拼音","translation" to "译文","note" to "注释"),l);val oldFlush=flush;flush={oldFlush();val target=Poetry.lines(draft).getOrNull(i);if(target!=null)listOf("original","pinyin","translation","note").forEach{target.addProperty(it,l.s(it))}};val moveActions=listOf("上移" to {persist();val all=flatten();if(i>0){java.util.Collections.swap(all,i,i-1);flush={};applyLines(all);lineList()}},"下移" to {persist();val all=flatten();if(i<all.lastIndex){java.util.Collections.swap(all,i,i+1);flush={};applyLines(all);lineList()}},"复制" to {persist();val all=flatten();all.add(i+1,all[i].deepCopy().apply{addProperty("id",Poetry.id())});flush={};applyLines(all);lineList()});val structureActions=listOf("拆分" to {persist();edit("在拆分处添加 |",l.s("original")){value->val parts=value.split('|').filter{it.isNotBlank()};require(parts.size>=2){"请添加拆分符 |"};val all=flatten();val first=all.removeAt(i);parts.forEachIndexed{j,text->all.add(i+j,first.deepCopy().apply{if(j>0){addProperty("id",Poetry.id());listOf("pinyin","translation","note").forEach{remove(it)}};addProperty("original",text)})};flush={};applyLines(all);message("首句保留原辅助内容，其余句请补充并校对译注。");lineList()}},"合并下一句" to {persist();val all=flatten();if(i<all.lastIndex){val a=all[i];val b=all.removeAt(i+1);a.addProperty("original",a.s("original")+b.s("original"));listOf("pinyin","translation","note").forEach{k->a.addProperty(k,listOf(a.s(k),b.s(k)).filter{it.isNotBlank()}.joinToString(" "))};flush={};applyLines(all);message("已保留首句 ID，请校对合并后的辅助内容。");lineList()}},"从本句新建分节" to {persist();val all=flatten();all[i].addProperty("_section",Poetry.id());flush={};flush={};applyLines(all);lineList()});panel.addView(ui.item("句子操作","移动、复制、拆分、合并和分节"){val actions=moveActions+structureActions;choose("句子操作",actions.map{it.first}){actions[it].second()}})}
    private fun save(){persist();work({poems.saveEdit(entry,draft.deepCopy(),base)}){discarded=true;flush={};finish()}}
    override fun onPause(){persist();super.onPause()}
    override fun navigateBack(){persist();finish()}
}
